package main

import (
	"errors"
	"fmt"
	"regexp"
	"slices"
	"strings"
	"unicode"
	"unicode/utf8"
)

const maxHeaderLen = 100

// types are the Conventional Commits types accepted by this repository.
var types = []string{"build", "chore", "ci", "docs", "feat", "fix", "perf", "refactor", "revert", "style", "test"}

var (
	headerRe = regexp.MustCompile(`^([A-Za-z]+)(?:\(([^()]+)\))?(!)?: (\S.*)$`)
	scopeRe  = regexp.MustCompile(`^[a-z0-9][a-z0-9._/-]*$`)
)

// exemptPrefixes are headers generated by git itself.
var exemptPrefixes = []string{"Merge ", `Revert "`, "fixup! ", "squash! ", "amend! "}

// Validate reports whether msg is a valid Conventional Commits 1.0 message.
// Git comment lines and everything below the scissors line are ignored.
func Validate(msg string) error {
	lines := clean(msg)
	if len(lines) == 0 || lines[0] == "" {
		return errors.New("commit message is empty")
	}

	header := lines[0]
	for _, p := range exemptPrefixes {
		if strings.HasPrefix(header, p) {
			return nil
		}
	}

	var errs []error

	if len(header) > maxHeaderLen {
		errs = append(errs, fmt.Errorf("header is %d characters, max is %d", len(header), maxHeaderLen))
	}

	if len(lines) > 1 && lines[1] != "" {
		errs = append(errs, errors.New("header must be followed by a blank line"))
	}

	m := headerRe.FindStringSubmatch(header)
	if m == nil {
		errs = append(errs, fmt.Errorf("header %q does not match format <type>(<scope>)!: <description>", header))
		return errors.Join(errs...)
	}

	typ, scope, desc := m[1], m[2], m[4]

	if !slices.Contains(types, typ) {
		errs = append(errs, fmt.Errorf("unknown type %q, allowed: %s", typ, strings.Join(types, ", ")))
	}

	if scope != "" && !scopeRe.MatchString(scope) {
		errs = append(errs, fmt.Errorf("scope %q must be lowercase (a-z, 0-9, . _ / -)", scope))
	}

	if first, _ := utf8.DecodeRuneInString(desc); unicode.IsUpper(first) {
		errs = append(errs, errors.New("description must start with a lowercase letter"))
	}

	if strings.HasSuffix(desc, ".") {
		errs = append(errs, errors.New("description must not end with a period"))
	}

	return errors.Join(errs...)
}

// clean drops git comments, the scissors section and trailing whitespace.
func clean(msg string) []string {
	var lines []string

	for line := range strings.Lines(msg) {
		if strings.HasPrefix(line, "# ") && strings.Contains(line, ">8") {
			break
		}

		if strings.HasPrefix(line, "#") {
			continue
		}

		lines = append(lines, strings.TrimRight(line, " \t\r\n"))
	}

	for len(lines) > 0 && lines[len(lines)-1] == "" {
		lines = lines[:len(lines)-1]
	}

	return lines
}
